import type { L10n, LogDef } from "@/engine/types";
import { t } from "./util";

// Crew audio logs. `order` is the discovery order, which is deliberately not the order in which the
// entries were recorded: the title carries the in-fiction stamp ("Haul day N" before the call,
// "Corridor, minute N" after it) so the player can put the story back together.
// The crew calls the player "Third" (cs "Trojka"), which keeps the Czech text free of gendered forms.

const AUTHORS = {
  captain: t("kapitánka Ingrid Halloranová", "Captain Ingrid Halloran"),
  quartermaster: t("skladník Bohumil Křepelka", "Quartermaster Bohumil \"Bob\" Křepelka"),
  intern: t("stážistka Pip Adeyemi", "Pip Adeyemi, intern"),
  cook: t("kuchařka Dolores „Dolly“ Quintanová", "Dolores \"Dolly\" Quintana, cook"),
  navigator: t("navigátor Teodor Lindqvist", "Navigator Teodor Lindqvist"),
  chief: t("šéftechnik Yusuf Demirci", "Chief Engineer Yusuf Demirci"),
  auditor: t("firemní revizor Clement Oduya", "Compliance Officer Clement Oduya"),
} satisfies Record<string, L10n>;

const log = (order: number, author: keyof typeof AUTHORS, title: L10n, cs: string, en: string): LogDef => ({
  id: `log_${String(order).padStart(2, "0")}`,
  author: AUTHORS[author],
  title,
  text: t(cs, en),
  order,
});

